ALTER TYPE "RoleCode" ADD VALUE IF NOT EXISTS 'INSTRUCTOR';
ALTER TYPE "RoleCode" ADD VALUE IF NOT EXISTS 'CLUB_OPERATOR';
ALTER TYPE "RoleCode" ADD VALUE IF NOT EXISTS 'ACCOUNTANT';
CREATE TYPE "ActivityStatus" AS ENUM ('ACTIVE','PAUSED','ARCHIVED');
CREATE TYPE "BookingStatus" AS ENUM ('RESERVED','CONFIRMED','COMPLETED','CANCELLED','NO_SHOW');
CREATE TYPE "InventoryStatus" AS ENUM ('AVAILABLE','ISSUED','MAINTENANCE','RETIRED');
ALTER TABLE "Student" ADD COLUMN IF NOT EXISTS "heightCm" DECIMAL(5,2), ADD COLUMN IF NOT EXISTS "weightKg" DECIMAL(5,2), ADD COLUMN IF NOT EXISTS "allergies" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "medicalNotes" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "behaviorNotes" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "independentStayAllowed" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "Activity" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "minAge" INTEGER NOT NULL DEFAULT 0, "maxAge" INTEGER NOT NULL DEFAULT 18, "minHeightCm" DECIMAL(5,2), "maxWeightKg" DECIMAL(5,2), "durationMinutes" INTEGER NOT NULL DEFAULT 60, "capacity" INTEGER NOT NULL DEFAULT 10, "season" TEXT NOT NULL DEFAULT 'ALL_YEAR', "requiresConsent" BOOLEAN NOT NULL DEFAULT true, "requiresInstructor" BOOLEAN NOT NULL DEFAULT true, "status" "ActivityStatus" NOT NULL DEFAULT 'ACTIVE', "courseId" UUID, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Activity_name_key" ON "Activity"("name"); CREATE INDEX "Activity_status_minAge_maxAge_idx" ON "Activity"("status","minAge","maxAge");
CREATE TABLE "Venue" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "zone" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "capacity" INTEGER NOT NULL DEFAULT 10, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "Venue_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Venue_name_key" ON "Venue"("name");
CREATE TABLE "InventoryItem" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "inventoryNo" TEXT NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 1, "status" "InventoryStatus" NOT NULL DEFAULT 'AVAILABLE', "notes" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "InventoryItem_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "InventoryItem_inventoryNo_key" ON "InventoryItem"("inventoryNo"); CREATE INDEX "InventoryItem_status_name_idx" ON "InventoryItem"("status","name");
CREATE TABLE "ActivityInventory" ("activityId" UUID NOT NULL, "itemId" UUID NOT NULL, "required" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "ActivityInventory_pkey" PRIMARY KEY ("activityId","itemId"));
CREATE TABLE "ParentConsent" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "parentId" UUID NOT NULL, "consentType" TEXT NOT NULL, "validFrom" DATE NOT NULL, "validUntil" DATE, "signedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "notes" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "ParentConsent_pkey" PRIMARY KEY ("id")); CREATE INDEX "ParentConsent_studentId_consentType_validUntil_idx" ON "ParentConsent"("studentId","consentType","validUntil");
CREATE TABLE "ActivityBooking" ("id" UUID NOT NULL, "studentId" UUID NOT NULL, "activityId" UUID NOT NULL, "venueId" UUID NOT NULL, "instructorId" UUID, "consentId" UUID, "startsAt" TIMESTAMPTZ(3) NOT NULL, "endsAt" TIMESTAMPTZ(3) NOT NULL, "status" "BookingStatus" NOT NULL DEFAULT 'RESERVED', "price" DECIMAL(14,2) NOT NULL, "notes" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "ActivityBooking_pkey" PRIMARY KEY ("id")); CREATE INDEX "ActivityBooking_startsAt_status_idx" ON "ActivityBooking"("startsAt","status"); CREATE INDEX "ActivityBooking_activityId_startsAt_idx" ON "ActivityBooking"("activityId","startsAt"); CREATE INDEX "ActivityBooking_venueId_startsAt_idx" ON "ActivityBooking"("venueId","startsAt"); CREATE INDEX "ActivityBooking_studentId_startsAt_idx" ON "ActivityBooking"("studentId","startsAt");
CREATE TABLE "InventoryIssue" ("id" UUID NOT NULL, "bookingId" UUID NOT NULL, "itemId" UUID NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 1, "issuedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "returnedAt" TIMESTAMPTZ(3), CONSTRAINT "InventoryIssue_pkey" PRIMARY KEY ("id")); CREATE INDEX "InventoryIssue_itemId_returnedAt_idx" ON "InventoryIssue"("itemId","returnedAt");
ALTER TABLE "Activity" ADD CONSTRAINT "Activity_courseId_fkey" FOREIGN KEY ("courseId") REFERENCES "Course"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ActivityInventory" ADD CONSTRAINT "ActivityInventory_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ActivityInventory_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ParentConsent" ADD CONSTRAINT "ParentConsent_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ParentConsent_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "Parent"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ActivityBooking" ADD CONSTRAINT "ActivityBooking_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ActivityBooking_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ActivityBooking_venueId_fkey" FOREIGN KEY ("venueId") REFERENCES "Venue"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ActivityBooking_instructorId_fkey" FOREIGN KEY ("instructorId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "ActivityBooking_consentId_fkey" FOREIGN KEY ("consentId") REFERENCES "ParentConsent"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "InventoryIssue" ADD CONSTRAINT "InventoryIssue_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "ActivityBooking"("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "InventoryIssue_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "InventoryItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
